--
-- Table structure for table `knowledge_articles`
--

DROP TABLE IF EXISTS `knowledge_articles`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `knowledge_articles` (
  `article_id` varchar(20) NOT NULL,
  `policy_id` varchar(60) NOT NULL,
  `title` varchar(200) NOT NULL,
  `content` text NOT NULL,
  `version` int NOT NULL,
  `effective_from` date NOT NULL,
  `effective_to` date DEFAULT NULL,
  `status` enum('Draft','Published','Expired','Archived') DEFAULT 'Draft',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`article_id`),
  UNIQUE KEY `policy_id` (`policy_id`,`version`),
  CONSTRAINT `knowledge_articles_ibfk_1` FOREIGN KEY (`policy_id`) REFERENCES `policy_documents` (`policy_id`),
  CONSTRAINT `knowledge_articles_chk_1` CHECK ((`version` > 0)),
  CONSTRAINT `knowledge_articles_chk_2` CHECK (((`effective_to` is null) or (`effective_to` >= `effective_from`)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

