CREATE TABLE `messages` (
  `message_id` varchar(60) NOT NULL,
  `ticket_id` varchar(30) NOT NULL,
  `sender_id` int DEFAULT NULL,
  `sender_type` enum('Student','Instructor','Admin','Support','System') NOT NULL,
  `message_text` text NOT NULL,
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`message_id`),
  KEY `sender_id` (`sender_id`),
  KEY `idx_message_ticket` (`ticket_id`),
  CONSTRAINT `messages_ibfk_1` FOREIGN KEY (`ticket_id`) REFERENCES `tickets` (`ticket_id`),
  CONSTRAINT `messages_ibfk_2` FOREIGN KEY (`sender_id`) REFERENCES `requesters` (`requester_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
