--
-- Table structure for table `tickets`
--

DROP TABLE IF EXISTS `tickets`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tickets` (
  `ticket_id` varchar(30) NOT NULL,
  `requester_id` int NOT NULL,
  `term_id` int NOT NULL,
  `category_id` int NOT NULL,
  `subject` varchar(200) NOT NULL,
  `description` text NOT NULL,
  `priority` enum('Low','Normal','High','Critical') DEFAULT 'Normal',
  `status` enum('Open','In Progress','Waiting','Escalated','Resolved','Closed') DEFAULT 'Open',
  `issue_type` varchar(50) DEFAULT 'normal',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`ticket_id`),
  KEY `term_id` (`term_id`),
  KEY `idx_ticket_requester` (`requester_id`),
  KEY `idx_ticket_category` (`category_id`),
  KEY `idx_ticket_status` (`status`),
  KEY `idx_ticket_created` (`created_at`),
  CONSTRAINT `tickets_ibfk_1` FOREIGN KEY (`requester_id`) REFERENCES `requesters` (`requester_id`),
  CONSTRAINT `tickets_ibfk_2` FOREIGN KEY (`term_id`) REFERENCES `terms` (`term_id`),
  CONSTRAINT `tickets_ibfk_3` FOREIGN KEY (`category_id`) REFERENCES `categories` (`category_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

